    result = [-1, -1]

    # Initialize hash map
    hash_map = {}

    # Iterate through array
    for i in range(len(arr)):
        # If element is already present in hash map
        if arr[i] in hash_map:
            # Increment its count
            hash_map[arr[i]] += 1
        else:
            # Add element to hash map with count 1
            hash_map[arr[i]] = 1

    # Iterate through array again
    for i in range(len(arr)):
        # If count of element is 1
